<?= $this->extend('layouts/auth') ?><?= $this->section('content') ?><main class="flex min-h-screen items-center justify-center p-4"><section class="card w-full max-w-md p-6 sm:p-8"><h1 class="text-2xl font-semibold"><?= esc($title ?? 'Verify code') ?></h1><p class="mt-2 text-sm text-gray-600"><?= esc($note ?? 'If this number is registered, we sent a code.') ?></p><?php if (session('message')): ?><p class="mt-4 rounded-lg bg-blue-50 p-3 text-sm text-blue-800"><?= esc(session('message')) ?></p><?php endif ?><?php if (session('error')): ?><p class="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800"><?= esc(session('error')) ?></p><?php endif ?><form class="mt-6 space-y-4" method="post" action="<?= esc($action ?? site_url('login/sms/verify')) ?>"><?= csrf_field() ?><div><label class="form-label" for="token">6-digit code</label><input class="form-control tracking-[.35em]" id="token" name="token" inputmode="numeric" autocomplete="one-time-code" minlength="6" maxlength="6" pattern="[0-9]{6}" required></div><button class="btn-primary w-full" type="submit">Verify and continue</button></form><form class="mt-3" method="post" action="<?= esc($resendAction??site_url('login/sms')) ?>"><?= csrf_field() ?><input type="hidden" name="mobile_no" value="<?= esc((string) session('otp_login_mobile')) ?>"><button class="min-h-11 w-full text-sm font-medium text-accent" type="submit">Resend code</button></form></section></main><?= $this->endSection() ?>
